mapper.select:
select product_id, model_id from ry_business.ry_rental_product
where tenant_id=#{tenantId} and member_id=#{memberId} and model_id=#{modelId}
  and (product_type=1 or product_type='device') and is_delete=0 order by product_id limit 1

select product_id, class_id, model_id, product_type from ry_business.ry_rental_product
where tenant_id=#{tenantId} and member_id=#{memberId} and product_id=#{productId}
  and (product_type=1 or product_type='device') and is_delete=0 limit 1

select model_id from ry_business.ry_rental_merchant_accessory_model
where tenant_id=#{tenantId} and member_id=#{memberId} and accessory_id=#{accessoryId}
  and model_id=#{modelId} and is_delete=0
